message.content:
{
  "candidate_edge_types": [
    {
      "name": "OBSERVED_DEFICIENCY_PROMPTS_ALTERNATIVE_RESOURCE_ACQUISITION",
      "definition": "An earlier observation that a currently available resource lacks a required component or contains an incompatibility prompts a subsequent action to obtain or inspect an alternative resource intended to supply the missing capability or resolve the problem.",
      "source_description": "An observation identifying a missing required component, incompatibility, or other deficiency in a currently available resource.",
      "target_description": "A subsequent agent action that acquires or inspects an alternative resource intended to address the observed deficiency."
    },
    {
      "name": "CONFIRMS_REQUIRED_CONTENTS_BEFORE_EXTRACTION",
      "definition": "An inspection of an archive or container that reveals the presence of task-relevant files or directories prompts a subsequent extraction or unpacking of that container.",
      "source_description": "An archive or container inspection result that identifies resources needed for the task.",
      "target_description": "A subsequent action that extracts or unpacks the inspected archive or container."
    },
    {
      "name": "PREPARES_BUILD_INPUTS_ACCORDING_TO_OBSERVED_BUILD_SPECIFICATION",
      "definition": "An observed build specification that defines required source files, headers, dependencies, or expected source-tree layout guides a subsequent action that places or arranges files to satisfy those build requirements.",
      "source_description": "An observed build file or configuration specification that states expected inputs, dependencies, or source layout.",
      "target_description": "A subsequent action that copies, renames, or arranges source or configuration files to conform to the observed build specification."
    },
    {
      "name": "COMPARES_ALTERNATIVE_IMPLEMENTATION_VARIANTS",
      "definition": "After a default or previously selected implementation or configuration variant has been identified, the agent performs a comparative inspection of an alternative variant to evaluate differences or suitability.",
      "source_description": "A default or previously selected implementation or configuration variant.",
      "target_description": "A subsequent comparative inspection or diff of an alternative implementation or configuration variant."
    },
    {
      "name": "OBSERVED_VARIANT_DIFFERENCES_INFORM_SOURCE_ADAPTATION",
      "definition": "Observed differences between implementation or configuration variants, such as those revealed by a diff, inform a subsequent modification or adaptation of the selected source or configuration files.",
      "source_description": "An observation of differences between alternative implementation or configuration variants.",
      "target_description": "A subsequent action that modifies or adapts source or configuration files based on those observed differences."
    }
  ]
}

